    modules["ui/autobuy"] = (function()
    -- ======================================================================
    -- ui/autobuy —— 自动购买界面
    -- 依赖：ui/assets, services/buymenu, ui/connect, ui/create, ui/icon, ui/metrics, ui/motion, ui/popup …
    -- 清理：删除无用语句 0 处，重命名 194 个变量
    -- ======================================================================
    return function(requireModule)
        local assetsUi = requireModule("ui/assets")
        local buymenuService = requireModule("services/buymenu")
        local connectUi = requireModule("ui/connect")
        local createUi = requireModule("ui/create")
        local iconUi = requireModule("ui/icon")
        local metricsUi = requireModule("ui/metrics")
        local motionUi = requireModule("ui/motion")
        local popupUi = requireModule("ui/popup")
        local service, skinUi = requireModule("core/service"), requireModule("ui/skin")
        local styleUi, themeUi = requireModule("ui/skins/style"), requireModule("ui/theme")
        local fontUi = requireModule("ui/font")
        local zindexUi = requireModule("ui/zindex")
        local result = service.get("RunService")
        local result2 = service.get("UserInputService")
        local value, autobuyFeature, state = styleUi.ANIM, {}, {}
        state.__index = state
        autobuyFeature.VIEW = 360
        autobuyFeature.INSET = 6
        autobuyFeature.ROW = 26
        autobuyFeature.HEADER = 15
        autobuyFeature.SEARCH_H = 22
        autobuyFeature.CHIP_H = 20
        autobuyFeature.ROW_GAP = 5
        autobuyFeature.CHIP_GAP = 6
        autobuyFeature.BAR_GAP = 10
        autobuyFeature.LIST_GAP = 12
        autobuyFeature.CHIP_PAD = 6
        autobuyFeature.CHIP_ICON = 11
        autobuyFeature.CHIP_ICON_GAP = 4
        autobuyFeature.ICON_W = 32
        autobuyFeature.COST_W = 40
        autobuyFeature.BADGE = 13
        autobuyFeature.RANK = 15
        autobuyFeature.GRIP = 9
        autobuyFeature.TEXT = 12
        autobuyFeature.SMALL = 10
        autobuyFeature.DRAG_SLOP = 3
        autobuyFeature.SYNC = 0.5
        autobuyFeature.FAST = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        autobuyFeature.TEAMS = {
            {key = "all", glyph = "wildcard"},
            {key = "Terrorists"},
            {key = "Counter-Terrorists"}
        }
        autobuyFeature.SORTS = {
            {key = "category", text = "category", glyph = "grid"},
            {key = "price", text = "price", glyph = "money"},
            {key = "name", text = "name", glyph = "letters"}
        }
        local state2 = {
            Terrorists = Color3.fromRGB(222, 168, 74),
            ["Counter-Terrorists"] = Color3.fromRGB(106, 160, 222)
        }

        local function helper(input)
            local autobuyFeature2, autobuyFeature3 = {}, {}
            if typeof(input) == "table" then
                for index, item in ipairs(input) do
                    if buymenuService.byName[item] and not autobuyFeature3[item] then
                        autobuyFeature3[item] = true
                        table.insert(autobuyFeature2, item)
                    end
                end
            end

            return autobuyFeature2, autobuyFeature3
        end

        local function checkAutobuy(object)
            if object.equipment or object.name == "Zeus x27" then
                return "Equipment"
            end

            return buymenuService.CATEGORY[object.kind] or "Equipment"
        end
        autobuyFeature.new = function(value2)
            value2 = typeof(value2) == "table" and value2 or {}
            local result3 = setmetatable(
                {
                    type = "autobuy",
                    flag = tostring(value2.flag or "autobuy_items"),
                    callback = typeof(value2.callback) == "function" and value2.callback or nil,
                    cards = {},
                    heads = {},
                    chips = {},
                    order = {},
                    chosen = {},
                    team = "all",
                    sort = "category",
                    descending = true,
                    query = "",
                    offer = nil,
                    lastSync = 0,
                    hasInit = false
                },
                state
            )
            result3.order, result3.chosen = helper(value2.value)

            return result3
        end
        state.Get = function(object)
            local autobuyFeature2 = {}
            for index, item in ipairs(object.order) do
                table.insert(autobuyFeature2, item)
            end

            return autobuyFeature2
        end
        state.commit = function(object, input)
            if object.onChanged then
                object.onChanged(object.flag, object:Get())
            end

            if not input and object.callback then
                pcall(object.callback, object:Get())
            end
        end
        state.Set = function(object, input, input2)
            object.order, object.chosen = helper(input)
            object:relayout()
            object:commit(input2)

            return object
        end
        state.indexOf = function(object, value2)
            for index, item in ipairs(object.order) do
                if item == value2 then
                    return index
                end
            end

            return nil
        end

        local function applyAutobuy(object, key, input, input2, input3)
            motionUi.cancel(object.tweens[key])
            object.tweens[key] = motionUi.to(input, input2, input3)
        end

        local function applyAutobuy2(object, input, value2)
            object.leaving = false
            local size2d = UDim2.new(0, 0, 0, value2)
            local value3 = (object.token or 0) + 1
            object.token = value3
            if object.main.Visible then
                applyAutobuy(object, "move", object.main, value.move, {Position = size2d})
                applyAutobuy(object, "scale", object.scale, value.move, {Scale = 1})

                return
            end
            object.main.Position = size2d + UDim2.fromOffset(value.enterFrom, 0)
            object.scale.Scale = value.enterScale
            object.main.Visible = true
            value2 = math.min(input, value.staggerMax) * value.stagger
            task.delay(
                value2,
                function()
                    if object.leaving or not object.main then
                        return
                    end

                    if object.token ~= value3 then
                        return
                    end
                    applyAutobuy(object, "move", object.main, value.enter, {Position = size2d})
                    applyAutobuy(object, "scale", object.scale, value.enter, {Scale = 1})
                end
            )
        end

        local function applyAutobuy3(object)
            if object.leaving or not object.main.Visible then
                object.leaving = true

                return
            end
            object.leaving = true
            local value2, value3, state3 = object.main, value.leave, {}
            state3.Position = object.main.Position + UDim2.fromOffset(value.leaveTo, 0)
            applyAutobuy(object, "move", value2, value3, state3)
            applyAutobuy(object, "scale", object.scale, value.leave, {Scale = value.leaveScale})
            task.delay(
                value.leave.Time,
                function()
                    if not object.leaving or not object.main then
                        return
                    end
                    object.main.Visible = false
                end
            )
        end
        state.matches = function(object, object2)
            if object.team ~= "all" and object2.team ~= "Both" and object2.team ~= object.team then
                return false
            end

            if object.query ~= "" and not object2.name:lower():find(object.query, 1, true) then
                return false
            end

            return true
        end
        state.relayout = function(object)
            if not object.scroller then
                return
            end
            local state3 = {}
            if #object.order > 0 then
                table.insert(state3, {piece = object.heads.queue, h = autobuyFeature.HEADER})
                for index, item in ipairs(object.order) do
                    index = object.cards[item]
                    if index then
                        table.insert(state3, {piece = index, h = autobuyFeature.ROW})
                    end
                end
            end
            local state4 = {}
            for index, item in ipairs(buymenuService.CATALOG) do
                if not object.chosen[item.name] and object:matches(item) then
                    table.insert(state4, item)
                end
            end
            local condition = object.descending and 1 or -1

            local function checkAutobuy2(object2, object3)
                if object2.cost ~= object3.cost then
                    return object2.cost > object3.cost == (condition == 1)
                end

                return object2.name < object3.name
            end

            if object.sort == "price" then
                table.sort(state4, checkAutobuy2)
            elseif object.sort == "name" then
                table.sort(
                    state4,
                    function(object2, object3)
                        return object2.name < object3.name == (condition == -1)
                    end
                )
            else
                local cache = {}
                for index, item in ipairs(buymenuService.CATEGORIES) do
                    cache[item] = index
                end
                table.sort(
                    state4,
                    function(input, input2)
                        local condition2, condition3 = 
                            cache[checkAutobuy(input)] or 99,
                            cache[checkAutobuy(input2)] or 99
                        if condition2 ~= condition3 then
                            return condition2 < condition3 == (condition == 1)
                        end

                        return checkAutobuy2(input, input2)
                    end
                )
            end
            local cache = {}
            if object.sort ~= "category" and #state4 > 0 then
                table.insert(state3, {piece = object.heads.catalog, h = autobuyFeature.HEADER})
            end
            local value2
            for index, item in ipairs(state4) do
                if object.sort == "category" then
                    index = checkAutobuy(item)
                    if index ~= value2 then
                        table.insert(state3, {piece = object.heads[index], h = autobuyFeature.HEADER})
                        value2 = index
                    end
                end
                table.insert(state3, {piece = object.cards[item.name], h = autobuyFeature.ROW})
            end
            state4 = 0
            for index, item in ipairs(state3) do
                cache[item.piece] = true
                applyAutobuy2(item.piece, index, state4)
                state4 = state4 + item.h + autobuyFeature.ROW_GAP
            end

            for index, item in pairs(object.cards) do
                if not cache[item] then
                    applyAutobuy3(item)
                end
            end

            for index, item in pairs(object.heads) do
                if not cache[item] then
                    applyAutobuy3(item)
                end
            end
            object.scroller.CanvasSize = UDim2.fromOffset(0, math.max(0, state4 - autobuyFeature.ROW_GAP))
            object:repaint()
        end
        state.paintCard = function(value2, key)
            local value3 = value2.cards[key]
            if not value3 then
                return
            end
            local result3, condition = value2:indexOf(key), value2.offer == nil or value2.offer[key] ~= nil
            value3.rank.Visible = result3 ~= nil
            value3.rank.Text = result3 and tostring(result3) or ""
            if value3.grip then
                value3.grip.Visible = result3 ~= nil
            end

            if result3 then
                value3.rank.BackgroundColor3 = themeUi.get()
                value3.main.BackgroundColor3 = themeUi.get()
                local value4, value5, state3 = value3.main, autobuyFeature.FAST, {}
                state3.BackgroundTransparency = value2.dragKey == key and 0.7 or 0.87
                applyAutobuy(value3, "fade", value4, value5, state3)
            else
                applyAutobuy(value3, "fade", value3.main, autobuyFeature.FAST, {BackgroundTransparency = 1})
            end
            value2 = condition and 0 or 0.55
            value3.label.TextTransparency = value2
            value3.cost.TextTransparency = value2
            value3.art.ImageTransparency = value2
            if value3.badge then
                value3.badge.ImageTransparency = value2
            end
            value3.label.TextColor3 = skinUi.get(result3 and "text" or "muted")
        end
        state.repaint = function(object)
            for index in pairs(object.cards) do
                object:paintCard(index)
            end
        end
        state.paintChip = function(object, object2, value2)
            local condition, backgroundColor3 = 
                (object2.group == "team" and object.team or object.sort) ==
                object2.key,
                themeUi.get()
            local condition2, value3, value4, state3 = 
                condition and
                backgroundColor3 or
                skinUi.get(value2 and "muted" or "dim"),
                object2.stroke,
                autobuyFeature.FAST,
                {}
            state3.Color = condition and backgroundColor3 or skinUi.get(value2 and "edge" or "stroke")
            applyAutobuy(object2, "tint", value3, value4, state3)
            value3, value4, value2 = object2.main, autobuyFeature.FAST, {}
            value2.BackgroundTransparency = condition and 0.88 or 1
            applyAutobuy(object2, "fill", value3, value4, value2)
            object2.main.BackgroundColor3 = backgroundColor3
            if object2.label then
                object2.label.TextColor3 = condition2
            end

            if object2.art then
                object2.art.ImageColor3 = object2.tint or condition2
            end
        end
        state.paintChips = function(object)
            for index, item in ipairs(object.chips) do
                object:paintChip(item, item.hovered)
            end

            if object.dirArt then
                object.dirArt.ImageContent = iconUi.get(object.descending and "sortDown" or "sortUp")
            end
        end
        state.toggle = function(object, key)
            if object.chosen[key] then
                object.chosen[key] = nil
                local result3 = object:indexOf(key)
                if result3 then
                    table.remove(object.order, result3)
                end
            else
                object.chosen[key] = true
                table.insert(object.order, key)
            end
            object:relayout()
            object:commit(false)
        end
        state.moveTo = function(object, input, value2)
            local result3 = object:indexOf(input)
            if not result3 or result3 == value2 then
                return
            end
            table.remove(object.order, result3)
            table.insert(object.order, math.clamp(value2, 1, #object.order + 1), input)
            object:relayout()
        end

        local function checkAutobuy2(value2)
            while value2 do
                if value2:IsA("GuiObject") and not value2.Visible then
                    return false
                end
                value2 = value2.Parent
            end

            return true
        end
        state.sync = function(object)
            if not object.main then
                return
            end
            local clock = os.clock()
            if clock - object.lastSync < autobuyFeature.SYNC then
                return
            end

            if not checkAutobuy2(object.main) then
                return
            end
            object.lastSync = clock
            clock = buymenuService.offer()
            if not clock then
                return
            end
            object.offer = clock
            object:repaint()
        end
        state.piece = function(input, input2)
            return {
                main = input2,
                scale = createUi.new("UIScale", {Parent = input2}),
                tweens = {},
                leaving = false
            }
        end
        state.header = function(input, input2, input3, input4, input5)
            local result3 = createUi.new(
                "TextLabel",
                {
                    Name = input3,
                    Size = UDim2.new(1, 0, 0, autobuyFeature.HEADER),
                    BackgroundTransparency = 1,
                    Text = input4,
                    TextSize = autobuyFeature.SMALL,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    FontFace = fontUi.face(),
                    TextColor3 = themeUi.get(),
                    Visible = false,
                    ZIndex = input5,
                    Parent = input2
                }
            )
            themeUi.follow(result3, "TextColor3")

            return input:piece(result3)
        end
        state.row = function(object, input, object2, input2)
            local parent = createUi.new(
                "TextButton",
                {
                    Name = object2.name,
                    Size = UDim2.new(1, 0, 0, autobuyFeature.ROW),
                    BackgroundColor3 = themeUi.get(),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    Text = "",
                    Visible = false,
                    ZIndex = input2,
                    Parent = input
                }
            )
            local result3, value2, state3 = object:piece(parent), createUi.new, {}
            state3.CornerRadius, state3.Parent = UDim.new(0, metricsUi.corner), parent
            value2("UICorner", state3)
            if object.gripArt then
                result3.grip = createUi.new(
                    "ImageLabel",
                    {
                        Name = "Grip",
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, 2, 0.5, 0),
                        Size = UDim2.fromOffset(autobuyFeature.GRIP, autobuyFeature.GRIP),
                        BackgroundTransparency = 1,
                        ImageContent = object.gripArt,
                        skin = {ImageColor3 = "dim"},
                        Visible = false,
                        ZIndex = input2 + 1,
                        Parent = parent
                    }
                )
            end
            result3.rank = createUi.new(
                "TextLabel",
                {
                    Name = "Rank",
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, autobuyFeature.GRIP + 3, 0.5, 0),
                    Size = UDim2.fromOffset(autobuyFeature.RANK, autobuyFeature.RANK),
                    BackgroundColor3 = themeUi.get(),
                    BorderSizePixel = 0,
                    Text = "",
                    TextSize = autobuyFeature.SMALL,
                    TextColor3 = Color3.new(1, 1, 1),
                    FontFace = fontUi.face(),
                    Visible = false,
                    ZIndex = input2 + 1,
                    Parent = parent
                }
            )
            createUi.new("UICorner", {CornerRadius = UDim.new(1, 0), Parent = result3.rank})
            value2 = autobuyFeature.GRIP + autobuyFeature.RANK + 6
            result3.art = createUi.new(
                "ImageLabel",
                {
                    Name = "Art",
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, value2, 0.5, 0),
                    Size = UDim2.fromOffset(autobuyFeature.ICON_W, autobuyFeature.ROW - 8),
                    BackgroundTransparency = 1,
                    ScaleType = Enum.ScaleType.Fit,
                    Image = object2.icon,
                    ZIndex = input2 + 1,
                    Parent = parent
                }
            )
            state3 = value2 + autobuyFeature.ICON_W + 5
            result3.label = createUi.new(
                "TextLabel",
                {
                    Name = "Label",
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, state3, 0.5, 0),
                    Size = UDim2.new(1, -(state3 + autobuyFeature.COST_W + autobuyFeature.BADGE + 10), 1, 0),
                    BackgroundTransparency = 1,
                    Text = object2.name,
                    TextSize = autobuyFeature.TEXT,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    FontFace = fontUi.face(),
                    skin = {TextColor3 = "muted"},
                    ZIndex = input2 + 1,
                    Parent = parent
                }
            )
            result3.cost = createUi.new(
                "TextLabel",
                {
                    Name = "Cost",
                    AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, -(autobuyFeature.BADGE + 7), 0.5, 0),
                    Size = UDim2.fromOffset(autobuyFeature.COST_W, autobuyFeature.ROW),
                    BackgroundTransparency = 1,
                    Text = "$" .. object2.cost,
                    TextSize = autobuyFeature.SMALL,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    FontFace = fontUi.face(),
                    skin = {TextColor3 = "dim"},
                    ZIndex = input2 + 1,
                    Parent = parent
                }
            )
            state3 = assetsUi.marketplace.team[object2.team]
            if state3 then
                result3.badge = createUi.new(
                    "ImageLabel",
                    {
                        Name = "Team",
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -4, 0.5, 0),
                        Size = UDim2.fromOffset(autobuyFeature.BADGE, autobuyFeature.BADGE),
                        BackgroundTransparency = 1,
                        ScaleType = Enum.ScaleType.Fit,
                        Image = state3,
                        ImageColor3 = state2[object2.team],
                        ZIndex = input2 + 1,
                        Parent = parent
                    }
                )
            end
            object:wireCard(result3, object2.name)

            return result3
        end
        state.wireCard = function(object, object2, key)
            connectUi.signal(
                object2.main.InputBegan,
                function(object3)
                    if object3.UserInputType == Enum.UserInputType.MouseButton1 then
                        object.dragKey = key
                        object.dragY = object3.Position.Y
                        object.dragFrom = object:indexOf(key)
                        object.dragMoved = false
                        object:paintCard(key)
                    elseif object3.UserInputType == Enum.UserInputType.MouseMovement then
                        if popupUi.blocks(object2.main) then
                            return
                        end

                        if object.chosen[key] then
                            return
                        end
                        object2.main.BackgroundColor3 = skinUi.get("rowGlow")
                        applyAutobuy(
                            object2,
                            "fade",
                            object2.main,
                            autobuyFeature.FAST,
                            {BackgroundTransparency = 0.94}
                        )
                    end
                end,
                "autobuy/down"
            )
            connectUi.signal(
                object2.main.InputEnded,
                function(object3)
                    if object3.UserInputType == Enum.UserInputType.MouseMovement then
                        if object.chosen[key] then
                            return
                        end
                        applyAutobuy(
                            object2,
                            "fade",
                            object2.main,
                            autobuyFeature.FAST,
                            {BackgroundTransparency = 1}
                        )
                    end
                end,
                "autobuy/out"
            )
        end
        state.wire = function(object)
            connectUi.signal(
                result2.InputChanged,
                function(value2)
                    if not object.dragKey then
                        return
                    end

                    if value2.UserInputType ~= Enum.UserInputType.MouseMovement then
                        return
                    end
                    local value3 = value2.Position.Y - object.dragY
                    if math.abs(value3) > autobuyFeature.DRAG_SLOP then
                        object.dragMoved = true
                    end

                    if not object.dragFrom then
                        return
                    end
                    value2 = autobuyFeature.ROW + autobuyFeature.ROW_GAP
