    modules["ui/backdrop"] = (function()
    -- ======================================================================
    -- ui/backdrop —— 背景
    -- 依赖：ui/backdrop_art, core/log, ui/raster, core/service
    -- 清理：删除无用语句 0 处，重命名 59 个变量
    -- ======================================================================
    return function(requireModule)
        local backdropArtUi = requireModule("ui/backdrop_art")
        local log = requireModule("core/log")
        local rasterUi = requireModule("ui/raster")
        local result, backdropFeature, result2, fromObject = 
            requireModule("core/service").get("AssetService"),
            {}
        local enabled = false

        local function buildBackdrop(value, value2)
            local create, value3 = buffer.create(value * value2 * 4), backdropArtUi.alpha
            local value4, value5, value6, value7 = #value3, 255 // (backdropArtUi.levels - 1), 1, 0
            while value6 < value4 do
                value2, value = string.byte(value3, value6), string.byte(value3, value6 + 1)
                value6 += 2
                if value2 > 0 then
                    local value8 = 16777215 + value2 * value5 * 16777216
                    for index = 1, value, 1 do
                        buffer.writeu32(create, value7 * 4, value8)
                        value7 += 1
                    end
                else
                    value7 += value
                end
            end

            return create
        end

        local function applyBackdrop(input, value, input2, input3, input4, input5, input6)
            for index = 0, input4 - 1, 1 do
                local value2 = input6 + index
                if value2 >= 0 and value2 < value then
                    local value3, value4 = index * input3, value2 * value
                    for index2 = 0, input3 - 1, 1 do
                        local value5 = input5 + index2
                        if value5 >= 0 and value5 < value then
                            local readu8 = buffer.readu8(input2, (value3 + index2) * 4 + 3)
                            if readu8 > 0 then
                                local value6 = (value4 + value5) * 4
                                local value7 = readu8 + buffer.readu8(input, value6 + 3) * (255 - readu8) // 255
                                value7 = if value7 > 255 then 255 else value7
                                buffer.writeu8(input, value6, 255)
                                buffer.writeu8(input, value6 + 1, 255)
                                buffer.writeu8(input, value6 + 2, 255)
                                buffer.writeu8(input, value6 + 3, value7)
                            end
                        end
                    end
                end
            end
        end

        local function checkBackdrop(input, input2)
            local ok, value = pcall(
                function()
                    local result3, value = buildBackdrop(input, input2), backdropArtUi.tile
                    local create, value2 = buffer.create(value * value * 4), backdropArtUi.blits
                    for index = 1, #value2, 2 do
                        applyBackdrop(create, value, result3, input, input2, value2[index], value2[index + 1])
                    end

                    return rasterUi.image(create, value, value, "backdrop")
                end
            )

            return ok and value or nil
        end
        backdropFeature.content = function()
            local enabledCopy = enabled
            if enabledCopy then
                local fromObjectCopy = fromObject

                return fromObjectCopy
            end
            enabled = true
            local value = backdropArtUi.sprite[1]
            local value2 = backdropArtUi.sprite[2]
            enabledCopy = rasterUi.supported()
            if enabledCopy then
                local ok, fromObjectCopy = pcall(
                    function()
                        local result3 = result:CreateEditableImage({Size = Vector2.new(value, value2)})
                        result3:WritePixelsBuffer(
                            Vector2.zero,
                            Vector2.new(value, value2),
                            buildBackdrop(value, value2)
                        )
                        result2 = result:CreateEditableImage(
                            {Size = Vector2.new(backdropArtUi.tile, backdropArtUi.tile)}
                        )
                        local value3 = backdropArtUi.blits
                        local value4 = #value3
                        for index = 1, value4, 2 do
                            local resultCopy = result2
                            resultCopy:DrawImage(
                                Vector2.new(value3[index], value3[index + 1]),
                                result3,
                                Enum.ImageCombineType.AlphaBlend
                            )
                        end
                        pcall(
                            function()
                                result3:Destroy()
                            end
                        )
                        fromObject = Content.fromObject(result2)
                    end
                )
                local condition = not ok or not fromObject
                if condition then
                    log.warn("backdrop", "needs EditableImage: %s", tostring(fromObjectCopy))
                    result2, fromObject = nil, nil
                end
                fromObjectCopy = fromObject

                return fromObjectCopy
            end
            fromObject = checkBackdrop(value, value2)
            enabledCopy = fromObject

            return enabledCopy
        end
        backdropFeature.tileSize = function()
            return backdropArtUi.tile
        end
        backdropFeature.reset = function()
            result2, fromObject, enabled = nil, nil, false
        end

        return backdropFeature
    end
    end)()

