                if not initFeature.watchingAccount and
                    typeof(initFeature.account) ==
                    "table" and
                    typeof(initFeature.account.subscribe) ==
                    "function" then
                    initFeature.watchingAccount = true
                    pcall(
                        initFeature.account.subscribe,
                        function()
                            pcall(stateUi.notify)
                        end
                    )
                end

                if not section then
                    return initFeature
                end
                initFeature.browse = browseUi.new(condition)
                section:adopt(initFeature.browse, condition)
                initFeature.detail = detailUi.new(condition)
                section:adopt(initFeature.detail, condition)
                initFeature.section = section
                condition = service.get("RunService")
                connectUi.signal(
                    condition.RenderStepped,
                    function()
                        local condition2 = initFeature.section and initFeature.section.main
                        if condition2 and condition2.Visible then
                            pcall(spinnerUi.step)
                        end
                    end,
                    "cloud/spin"
