                return initFeature
            end,
            RESTORE_TRIES = 4,
            RESTORE_WAIT = 1.5,
            restoreLast = function(input, input2)
                local function applyInit(input3, input4, input5)
                    if typeof(input2) == "function" then
                        pcall(input2, input3, input4, input5)
                    end
                end

                if input then
                    applyInit(nil)

                    return
                end
                local value = 0

                local function applyInit2()
                    value += 1
                    sourceUi.last(
                        function(object, text)
                            if text then
                                local valueCopy = value
                                if valueCopy < initFeature.RESTORE_TRIES then
                                    task.delay(initFeature.RESTORE_WAIT, applyInit2)

                                    return
                                end
                                log.warn(
                                    "cloud",
                                    "restore: desisti depois de %d tentativas: %s",
                                    value,
                                    tostring(text)
                                )

                                return applyInit(nil, text)
                            end

                            if typeof(object) ~= "table" or not object.id then
                                return applyInit(nil, nil, true)
                            end
                            sourceUi.apply(
                                object,
                                function(input3, text2)
                                    if not input3 then
                                        log.warn(
                                            "cloud",
                                            "restore: %q nao abriu: %s",
                                            tostring(object.name),
                                            tostring(text2)
                                        )

                                        return applyInit(nil, text2)
                                    end
                                    dataUi.rememberLast(object)
