    modules["ui/cloud/report"] = (function()
    -- ======================================================================
    -- ui/cloud/report —— 界面：举报
    -- 依赖：ui/connect, ui/popup, cloud/report
    -- 清理：删除无用语句 0 处，重命名 10 个变量
    -- ======================================================================
    return function(requireModule)
        local connectUi = requireModule("ui/connect")
        local popupUi = requireModule("ui/popup")
        local reportFeature
        reportFeature = {
            REASON_MAX = 500,
            attach = function(object, input)
                local result = popupUi.new(object)
                if not result then
                    return nil
                end
                local condition = typeof(input) == "table" and input or {}
                local instance = result:AddBox(
                    {
                        text = "reason",
                        flag = "cloud_report_reason",
                        scope = "menu",
                        placeholder = "what is wrong with it"
                    }
                )
                result:AddButton(
                    {
                        text = "report",
                        icon = "caution",
                        tip = "flags it for a human to look at; nothing comes down automatically",
                        callback = function()
                            local text = tostring(instance:Get() or ""):gsub("^%s+", ""):gsub("%s+$", "")
                            if text == "" then
                                return
                            end

                            if #text > reportFeature.REASON_MAX then
                                text = text:sub(1, reportFeature.REASON_MAX)
                            end

                            if typeof(condition.onReport) == "function" then
                                pcall(condition.onReport, text)
                            end
                            instance:Set("")
                            result:Close()
                        end
                    }
                )
                connectUi.signal(
                    object.MouseButton1Click,
                    function()
                        result:Toggle()
                    end,
                    "cloud/report"
                )

                return result
            end
        }

        return reportFeature
    end
    end)()

    modules["ui/cloud/revise"] = (function()
    -- ======================================================================
    -- ui/cloud/revise —— 界面：修订
    -- 依赖：ui/connect, ui/popup, cloud/revise
    -- 清理：删除无用语句 0 处，重命名 9 个变量
    -- ======================================================================
    return function(requireModule)
        local connectUi = requireModule("ui/connect")
        local popupUi = requireModule("ui/popup")

        return {
            attach = function(object, input)
                local result = popupUi.new(object)
                if not result then
                    return nil
                end
                local condition = typeof(input) == "table" and input or {}
                local instance = result:AddBox(
                    {
                        text = "changed",
                        flag = "cloud_rev_changes",
                        scope = "menu",
                        lines = 3,
                        placeholder = "+ added\n- removed"
                    }
                )
                result:AddButton(
                    {
                        text = "publish version",
                        tip = "makes a new version from the values in the menu right now",
                        callback = function()
                            if typeof(condition.onRevise) == "function" then
                                pcall(condition.onRevise, {changes = instance:Get()})
                            end
                            result:Close()
                        end
                    }
                )
                local value = function()
                    result:Toggle()
                end
                connectUi.signal(object.MouseButton1Click, value, "cloud/revise")

                return result
            end
        }
    end
    end)()

