    modules["ui/cloud/state"] = (function()
    -- ======================================================================
    -- ui/cloud/state —— 界面：状态
    -- 依赖：ui/cloud/data, core/log
    -- 清理：删除无用语句 0 处，重命名 18 个变量
    -- ======================================================================
    return function(requireModule)
        local dataUi = requireModule("ui/cloud/data")
        local log = requireModule("core/log")
        local stateFeature = {scope = dataUi.PRIVATE, LIBRARY = "library", CONFIG = "config"}
        stateFeature.step = stateFeature.LIBRARY
        stateFeature.selected = nil
        stateFeature.query = ""
        local state = {}
        stateFeature.subscribe = function(input, input2)
            if typeof(input) == "function" then
                table.insert(state, {run = input, name = input2 or "?"})
            end

            return input
        end
        stateFeature.notify = function()
            for index, item in ipairs(state) do
                local ok, value = pcall(item.run)
                if not ok then
                    log.warn("cloud", "card %q falhou ao repintar: %s", item.name, tostring(value))
                end
            end
        end
        stateFeature.entry = function()
            local list = dataUi.list(stateFeature.scope, stateFeature.query)
            if stateFeature.selected then
                for index, item in ipairs(list) do
                    if item.id == stateFeature.selected then
                        return item
                    end
                end
            end

            return list[1]
        end
        local setScope = function(scope)
            if stateFeature.scope == scope then
                return
            end
            stateFeature.scope = scope
            stateFeature.selected = nil
            stateFeature.query = ""
            dataUi.setQuery("")
            stateFeature.notify()
        end
        stateFeature.setScope = setScope
        stateFeature.open = function(selected)
            if stateFeature.selected == selected and stateFeature.step == stateFeature.CONFIG then
                return
            end
            stateFeature.selected = selected
            stateFeature.step = stateFeature.CONFIG
            stateFeature.notify()
        end
        stateFeature.back = function()
            if stateFeature.step == stateFeature.LIBRARY then
                return
            end
            stateFeature.step = stateFeature.LIBRARY
            stateFeature.notify()
        end
        stateFeature.setQuery = function(value)
            value = typeof(value) == "string" and value or ""
            if stateFeature.query == value then
                return
            end
            stateFeature.query = value
            stateFeature.notify()
        end
        dataUi.onChange(
            function()
                stateFeature.notify()
            end
        )
        stateFeature.reset = function()
            state = {}
            stateFeature.scope = dataUi.PRIVATE
            stateFeature.step = stateFeature.LIBRARY
            stateFeature.selected = nil
            stateFeature.query = ""
        end

        return stateFeature
    end
    end)()

    modules["ui/cloud/upload"] = (function()
    -- ======================================================================
    -- ui/cloud/upload —— 界面：上传
    -- 依赖：ui/connect, ui/popup, cloud/upload
    -- 清理：删除无用语句 6 处，重命名 15 个变量
    -- ======================================================================
    return function(requireModule)
        local connectUi = requireModule("ui/connect")
        local popupUi = requireModule("ui/popup")
        local uploadFeature
        uploadFeature = {
            SCOPES = {"private", "public"},
            attach = function(object, input)
                local result = popupUi.new(object)
                if not result then
                    return nil
                end
                local condition = typeof(input) == "table" and input or {}
                local instance = result:AddBox(
                    {
                        text = "name",
                        flag = "cloud_up_name",
                        scope = "menu",
                        placeholder = "what people will see"
                    }
                )
                local instance2 = result:AddBox(
                    {
                        text = "about",
                        flag = "cloud_up_about",
                        scope = "menu",
                        placeholder = "one line on what it is for"
                    }
                )
                local instance3 = result:AddList(
                    {
                        text = "visibility",
                        tip = "private keeps it to your allowlist",
                        flag = "cloud_up_visibility",
                        scope = "menu",
                        values = uploadFeature.SCOPES,
                        value = uploadFeature.SCOPES[1]
                    }
                )
                local instance4 = result:AddBox(
                    {
                        text = "changed",
                        flag = "cloud_up_changes",
                        scope = "menu",
                        lines = 3,
                        placeholder = "+ added\n- removed"
                    }
                )
                local value = function()
                    if typeof(condition.onPublish) ~= "function" then
                        return
                    end
                    pcall(
                        condition.onPublish,
                        {
                            name = instance:Get(),
                            about = instance2:Get(),
                            visibility = instance3:Get(),
                            changes = instance4:Get()
                        }
                    )
                    result:Close()
                end
                result:AddButton({text = "publish", tip = "sends this config to the cloud", callback = value})
                local value2 = object.MouseButton1Click
                local value3 = function()
                    result:Toggle()
                end
                connectUi.signal(value2, value3, "cloud/upload")

                return result
            end
        }

        return uploadFeature
    end
    end)()

