    modules["ui/components/color"] = (function()
    -- ======================================================================
    -- ui/components/color —— 界面：components color
    -- 依赖：ui/components/base, ui/skin, ui/connect, ui/create, ui/metrics, ui/motion, ui/colorpicker, ui/popup …
    -- 清理：删除无用语句 0 处，重命名 119 个变量
    -- ======================================================================
    return function(requireModule)
        local baseUi, skinUi = requireModule("ui/components/base"), requireModule("ui/skin")
        local connectUi = requireModule("ui/connect")
        local createUi = requireModule("ui/create")
        local metricsUi = requireModule("ui/metrics")
        local motionUi = requireModule("ui/motion")
        local colorpickerUi = requireModule("ui/colorpicker")
        local popupUi = requireModule("ui/popup")
        local themeUi = requireModule("ui/theme")
        local fontUi = requireModule("ui/font")
        local zindexUi, colorFeature, state = 
            requireModule("ui/zindex"),
            {
            ALPHA_KEY = "_alpha",
            GRAD_KEY = "_grad",
            GRAD_COLOR_KEY = "_grad_b",
            GRAD_ANGLE_KEY = "_grad_angle",
            GRAD_ANGLE = 90,
            RAMP_ANGLE = 90
        },
            {__index = baseUi}
        local index = setmetatable({}, state)
        index.__index = index

        local function checkColor(input)
            if typeof(input) == "Color3" then
                return input
            end

            return Color3.fromRGB(255, 255, 255)
        end

        local function checkColor2(input)
            if typeof(input) ~= "number" then
                return 1
            end

            return math.clamp(input, 0, 1)
        end

        local function buildColor(list)
            if typeof(list) ~= "table" or #list == 0 then
                return nil, nil
            end
            local colorFeature2, colorFeature3 = {}, {}
            for index2, item in ipairs(list) do
                index2 = {}
                for index3, item2 in ipairs(item.stops or {}) do
                    index3 = tostring(item2.flag)
                    table.insert(index2, index3)
                    if not colorFeature3[index3] then
                        colorFeature3[index3] = {
                            color = checkColor(item2.value),
                            alpha = checkColor2(item2.alpha)
                        }
                    end
                end
                table.insert(
                    colorFeature2,
                    {
                        key = tostring(item.key),
                        label = tostring(item.label or item.key),
                        stops = index2,
                        ruler = item.ruler == true
                    }
                )
            end

            return colorFeature2, colorFeature3
        end
        colorFeature.new = function(value)
            value = typeof(value) == "table" and value or {}
            local text, result, value2 = tostring(value.text or "color"), buildColor(value.modes)

            return setmetatable(
                {
                    modes = result,
                    stops = value2,
                    mode = result and tostring(value.value or result[1].key) or nil,
                    type = "color",
                    text = text,
                    tip = value.tip and tostring(value.tip) or nil,
                    flag = tostring(value.flag or text),
                    value = checkColor(value.value or value.color),
                    alpha = checkColor2(value.alpha),
                    gradient = typeof(value.gradient) ==
                        "table" and
                        {
                        on = false,
                        color = checkColor(value.gradient.value),
                        alpha = checkColor2(value.gradient.alpha),
                        angle = typeof(value.gradient.angle) ==
                            "number" and
                            value.gradient.angle or
                            colorFeature.GRAD_ANGLE
                    } or
                        nil,
                    callback = typeof(value.callback) == "function" and value.callback or nil,
                    subcount = 0,
                    hasInit = false
                },
                index
            )
        end
        colorFeature.Color = index
        index.Get = function(object)
            if object.modes then
                return object.mode
            end

            return object.value
        end
        index.GetStops = function(object)
            if not object.stops then
                return nil
            end
            local colorFeature2 = {}
            for index2, item in pairs(object.stops) do
                colorFeature2[index2] = {color = item.color, alpha = item.alpha}
            end

            return colorFeature2
        end
        index.SetStops = function(object, input, input2)
            if not object.stops or typeof(input) ~= "table" then
                return object
            end

            for index2, item in pairs(input) do
                if object.stops[index2] and typeof(item) == "table" then
                    object.stops[index2].color = checkColor(item.color or object.stops[index2].color)
                    if typeof(item.alpha) == "number" then
                        object.stops[index2].alpha = checkColor2(item.alpha)
                    end
                end
            end
            object:mirrorStops()
            object:repaint()
            if not input2 and object.callback then
                pcall(object.callback, object.mode, object.stops)
            end

            return object
        end
        index.mirrorStops = function(object)
            if not object.onChanged or not object.stops then
                return
            end

            for index2, item in pairs(object.stops) do
                object.onChanged(index2, item.color)
                object.onChanged(index2 .. colorFeature.ALPHA_KEY, item.alpha)
            end
        end
        index.mirrorRamp = function(object)
            if not object.modes or not object.onChanged then
                return
            end
            object.onChanged(object.flag, object.mode)
            object:mirrorStops()
        end
        index.activeStops = function(object)
            if not object.modes then
                return {}
            end

            for colorFeature2, item in ipairs(object.modes) do
                if item.key == object.mode then
                    colorFeature2 = {}
                    for index2, item2 in ipairs(item.stops) do
                        index2 = object.stops[item2]
                        if index2 then
                            table.insert(colorFeature2, {color = index2.color, alpha = index2.alpha})
                        end
                    end

                    return colorFeature2, item
                end
            end

            return {}
        end
        index.GetAlpha = function(object)
            return object.alpha
        end
        index.mirrorAlpha = function(object)
            if object.onChanged then
                object.onChanged(object.flag .. colorFeature.ALPHA_KEY, object.alpha)
            end
        end
        index.GetGradient = function(object)
            if not object.gradient then
                return nil
            end

            return {
                on = object.gradient.on,
                color = object.gradient.color,
                alpha = object.gradient.alpha,
                angle = object.gradient.angle
            }
        end
        index.mirrorGradient = function(object)
            if not object.onChanged or not object.gradient then
                return
            end
            object.onChanged(object.flag .. colorFeature.GRAD_KEY, object.gradient.on)
            object.onChanged(object.flag .. colorFeature.GRAD_COLOR_KEY, object.gradient.color)
            object.onChanged(
                object.flag .. colorFeature.GRAD_COLOR_KEY .. colorFeature.ALPHA_KEY,
                object.gradient.alpha
            )
            object.onChanged(object.flag .. colorFeature.GRAD_ANGLE_KEY, object.gradient.angle)
        end
        index.SetGradient = function(object, object2, input)
            if not object.gradient or typeof(object2) ~= "table" then
                return object
            end
            object.gradient.on = object2.on and true or false
            object.gradient.color = checkColor(object2.color or object.gradient.color)
            if typeof(object2.alpha) == "number" then
                object.gradient.alpha = checkColor2(object2.alpha)
            end

            if typeof(object2.angle) == "number" then
                object.gradient.angle = object2.angle
            end
            object:mirrorGradient()
            object:repaint()
            if not input and object.callback then
                pcall(object.callback, object.value, object.alpha)
            end

            return object
        end
        index.repaint = function(object)
            if not object.hasInit then
                return
            end
            motionUi.cancel(object.stateTween)
            object.stateTween = nil
            if object.modes then
                local result = object:activeStops()
                local value = #result
                if value == 0 then
                    object.ramp.Enabled = false
                    object.swatch.BackgroundTransparency = 1

                    return
                end

                if value == 1 then
                    object.ramp.Enabled = false
                    object.swatch.BackgroundColor3 = result[1].color
                    object.swatch.BackgroundTransparency = 1 - result[1].alpha

                    return
                end
                local state2, state3 = {}, {}
                for index2, item in ipairs(result) do
                    local value2 = (index2 - 1) / (value - 1)
                    table.insert(state2, ColorSequenceKeypoint.new(value2, item.color))
                    table.insert(state3, NumberSequenceKeypoint.new(value2, 1 - item.alpha))
                end
                object.swatch.BackgroundColor3 = Color3.new(1, 1, 1)
                object.swatch.BackgroundTransparency = 0
                object.ramp.Color = ColorSequence.new(state2)
                object.ramp.Transparency = NumberSequence.new(state3)
                object.ramp.Rotation = colorFeature.RAMP_ANGLE
                object.ramp.Enabled = true

                return
            end
            local value = object.gradient
            if value and value.on then
                object.swatch.BackgroundColor3 = Color3.new(1, 1, 1)
                object.swatch.BackgroundTransparency = 0
                object.ramp.Color = ColorSequence.new(object.value, value.color)
                object.ramp.Transparency = NumberSequence.new(
                    {
                        NumberSequenceKeypoint.new(0, 1 - object.alpha),
                        NumberSequenceKeypoint.new(1, 1 - value.alpha)
                    }
                )
                object.ramp.Rotation = value.angle
                object.ramp.Enabled = true

                return
