        index.SetValues = function(object, value)
            object.values = typeof(value) == "table" and value or {}
            value = {}
            for index2, item in ipairs(object.values) do
                value[tostring(item)] = true
            end

            for index2 in pairs(object.chosen) do
                if not value[index2] then
                    object.chosen[index2] = nil
                end
            end

            if object.popup and object.popup.content then
                for index2, item in pairs(object.rows) do
                    pcall(
                        function()
                            item:Destroy()
                        end
                    )
                end
                object.marks = {}
                object.rows = {}
                for index2, item in ipairs(object.values) do
                    object.marks[item] = object:row(
                        object.popup.content,
                        index2 + listFeature.ORDER_ROWS - 1,
                        item
                    )
                end

                if object.search then
                    object:filter(object.search.Text)
                end
            else
                object.marks = {}
                object.rows = {}
            end
            object:refresh()

            return object
        end
