                value2(value3, value4, state2)
            end

            if object.onChanged then
                object.onChanged(object.flag, object.state)
            end

            if not input and object.callback then
                pcall(object.callback, object.state)
            end

            return object
        end
        toggleFeature.Toggle = index

        return toggleFeature
    end
    end)()

