    modules["ui/fade"] = (function()
    -- ======================================================================
    -- ui/fade —— 淡入淡出
    -- 清理：删除无用语句 0 处，重命名 35 个变量
    -- ======================================================================
    return function(input)
        local fadeFeature, state = {}, {__mode = "k"}
        local result = setmetatable({}, state)

        local function checkFade(key, key2)
            local value = result[key]

            return value and value[key2] or nil
        end

        local function applyFade(key, key2, value)
            local value2 = result[key]
            if not value2 then
                value2 = {}
                result[key] = value2
            end
            value2[key2] = value
        end

        local function applyFade2(key, key2)
            local value = result[key]
            if value then
                value[key2] = nil
            end
        end
        local state2, state3 = 
            {TextLabel = true, TextButton = true, TextBox = true},
            {ImageLabel = true, ImageButton = true, ViewportFrame = true}
        fadeFeature.record = function(input2, entry, key)
            local result2 = checkFade(entry, key)
            if result2 then
                if result2 < 1 then
                    table.insert(input2, {object = entry, property = key, original = result2})
                end

                return
            end
            local ok, value = pcall(
                function()
                    return entry[key]
                end
            )
            if ok and typeof(value) == "number" and value < 1 then
                table.insert(input2, {object = entry, property = key, original = value})
            end
        end
        fadeFeature.snapshot = function(instance)
            local fadeFeature2 = {}
            if not instance then
                return fadeFeature2
            end
            local result2 = instance:GetDescendants()
            table.insert(result2, instance)
            for index, item in ipairs(result2) do
                if item:IsA("UIStroke") then
                    fadeFeature.record(fadeFeature2, item, "Transparency")
                elseif item:IsA("GuiObject") then
                    fadeFeature.record(fadeFeature2, item, "BackgroundTransparency")
                    instance = item.ClassName
                    if state2[instance] then
                        fadeFeature.record(fadeFeature2, item, "TextTransparency")
                    end

                    if state3[instance] then
                        fadeFeature.record(fadeFeature2, item, "ImageTransparency")
                    end

                    if instance == "ScrollingFrame" then
                        fadeFeature.record(fadeFeature2, item, "ScrollBarImageTransparency")
                    end
                end
            end

            return fadeFeature2
        end
        fadeFeature.apply = function(input2, value)
            local condition = value <= 0
            for index, item in ipairs(input2) do
                item.object[item.property] = item.original + (1 - item.original) * value
                if condition then
                    applyFade2(item.object, item.property)
                else
                    applyFade(item.object, item.property, item.original)
                end
            end
        end

        return fadeFeature
    end
    end)()

    modules["ui/font"] = (function()
    -- ======================================================================
    -- ui/font —— 字体
    -- 依赖：ui/font_art, ui/customfont, ui/font_tiny5_art
    -- 清理：删除无用语句 0 处，重命名 48 个变量
    -- ======================================================================
    return function(requireModule)
        local fontArtUi = requireModule("ui/font_art")
        local customfontUi = requireModule("ui/customfont")
        local fontTiny5ArtUi, fontFeature, value, value2 = 
            requireModule("ui/font_tiny5_art"),
            {
            families = {
                Arimo = true,
                SourceSansPro = true,
                Gotham = true,
                Inconsolata = true,
                Merriweather = true,
                Nunito = true,
                Ubuntu = true
            },
            family = "Arimo"
        }
        fontFeature.MONO = "Inconsolata"
        fontFeature.PIXEL_STEP = 8
        local cache = {}
        fontFeature.face = function(ok)
            local value3 = (value or fontFeature.family) .. (ok and "/b" or "/r")
            local value4 = cache[value3]
            if value4 then
                local cacheCopy = cache

                return cacheCopy[value3]
            end
            local condition = ok and Enum.FontWeight.Bold or Enum.FontWeight.Regular
            ok, value4 = pcall(
                function()
                    local valueCopy = value
                    if valueCopy then
                        local value5, valueCopy2 = Font.new, value

                        return value5(valueCopy2, condition, Enum.FontStyle.Normal)
                    end

                    return Font.fromName(fontFeature.family, condition, Enum.FontStyle.Normal)
                end
            )
            if not ok or not value4 then
                ok, value4 = pcall(
                    function()
                        return Font.fromEnum(Enum.Font.SourceSans)
                    end
                )
            end

            if not ok or not value4 then
                return nil
            end
            cache[value3] = value4

            return value4
        end
        fontFeature.setFamily = function(key)
            if not fontFeature.families[key] then
                return false
            end
            fontFeature.family = key
            cache = {}

            return true
        end

        local function helper(object)
            local fontFeature2 = {}
            for index, item in pairs(object.faces or {}) do
                fontFeature2[index] = {}
                for index2, item2 in pairs(item) do
                    fontFeature2[index][index2] = {b64 = item2}
                end
            end

            return fontFeature2
        end
        fontFeature.loadCustom = function(condition)
            local result = helper(fontArtUi)
            if typeof(condition) == "table" then
                for index, item in pairs(condition) do
                    item = if typeof(item) == "string" then {normal = item} else item
                    if typeof(item) == "table" then
                        result[index] = result[index] or {}
                        for index2, item2 in pairs(item) do
                            if not result[index][index2] then
                                result[index][index2] = item2
                            end
                        end
                    end
                end
            end
            condition = fontArtUi.family or "Menu"
            if not customfontUi.load(result, condition) then
                return false
            end
            value = customfontUi.uris[condition]
            condition = value
            if not condition then
                return false
            end
            cache = {}

            return true
        end
        fontFeature.loadPixel = function()
            local valueCopy = value2
            if valueCopy then
                return true
            end
            valueCopy = fontTiny5ArtUi.family or "Pixel"
            if not customfontUi.load(helper(fontTiny5ArtUi), valueCopy) then
                return false
            end
            value2 = customfontUi.uris[valueCopy]
            valueCopy = value2

            return valueCopy ~= nil
        end
        fontFeature.pixel = function()
            local valueCopy = value2
            if not valueCopy then
                return fontFeature.face(true)
            end
            valueCopy = value2 .. "/px"
            local value3 = cache[valueCopy]
            if value3 then
                local cacheCopy = cache

                return cacheCopy[valueCopy]
            end
            local ok, value4 = pcall(
                function()
                    local value4, valueCopy2 = Font.new, value2

                    return value4(valueCopy2, Enum.FontWeight.Regular, Enum.FontStyle.Normal)
                end
            )
            if not ok or not value4 then
                return fontFeature.face(true)
            end
            cache[valueCopy] = value4

            return value4
        end
        fontFeature.mono = function()
            local value3 = fontFeature.MONO .. "/mono"
            local value4 = cache[value3]
            if value4 then
                local cacheCopy = cache

                return cacheCopy[value3]
            end
            local ok, value5 = pcall(
                function()
                    return Font.fromName(fontFeature.MONO, Enum.FontWeight.Regular, Enum.FontStyle.Normal)
                end
            )
            if not ok or not value5 then
                return fontFeature.face()
            end
            cache[value3] = value5

            return value5
        end
        fontFeature.refresh = function(instance)
            if not instance then
                return 0
            end
            local face = fontFeature.face()
            if not face then
                return 0
            end
            local value3 = 0
            for index, item in ipairs(instance:GetDescendants()) do
                value3 = if item:IsA("TextLabel") or item:IsA("TextButton") or item:IsA("TextBox") then
                    if pcall(
                        function()
                            item.FontFace = face
                        end
                    ) then
                        value3 + 1
    else
                        value3
    else
                    value3
            end

            return value3
        end
        fontFeature.report = function()
            if #customfontUi.report == 0 then
                return nil
            end

            return table.concat(customfontUi.report, " ")
        end

        return fontFeature
    end
    end)()

