    modules["ui/icon"] = (function()
    -- ======================================================================
    -- ui/icon —— 图标
    -- 依赖：ui/icon_art, services/png, ui/raster
    -- 清理：删除无用语句 0 处，重命名 30 个变量
    -- ======================================================================
    return function(requireModule)
        local iconArtUi = requireModule("ui/icon_art")
        local pngService = requireModule("services/png")
        local rasterUi, iconFeature, cache = requireModule("ui/raster"), {}, {}

        local function helper(list, value)
            local create, value2, value3 = buffer.create(value * 4), 1, 0
            while value2 < #list and value3 < value do
                local byte, byte2 = string.byte(list, value2), string.byte(list, value2 + 1)
                value2 += 2
                for index = 1, byte2, 1 do
                    if value3 >= value then
                        break
                    end
                    index = value3 * 4
                    buffer.writeu8(create, index, 255)
                    buffer.writeu8(create, index + 1, 255)
                    buffer.writeu8(create, index + 2, 255)
                    buffer.writeu8(create, index + 3, byte)
                    value3 += 1
                end
            end

            return create
        end
        iconFeature.fromAlpha = function(list, input, value)
            if typeof(list) ~= "string" or #list == 0 then
                return nil
            end
            value = value or input

            return rasterUi.image(helper(list, input * value), input, value, "icon")
        end
        iconFeature.get = function(key)
            local value = cache[key]
            if value ~= nil then
                return value or nil
            end
            value = iconArtUi.glyphs and iconArtUi.glyphs[key]
            if not value then
                cache[key] = false

                return nil
            end
            local fromAlpha = iconFeature.fromAlpha(value.data, value.w, value.h)
            cache[key] = fromAlpha or false

            return fromAlpha
        end
        local cache2 = {}
        iconFeature.bytes = function(key)
            local value = cache2[key]
            if value ~= nil then
                return value or nil
            end
            local condition = iconArtUi.glyphs and iconArtUi.glyphs[key]
            if not condition then
                cache2[key] = false

                return nil
            end
            local ok, value2 = pcall(
                function()
                    return pngService.encode(
                        condition.w,
                        condition.h,
                        buffer.tostring(helper(condition.data, condition.w * condition.h))
                    )
                end
            )
            cache2[key] = ok and value2 or false

            return cache2[key] or nil
        end
        iconFeature.dimensions = function(key)
            local condition = iconArtUi.glyphs and iconArtUi.glyphs[key]
            if not condition then
                return nil
            end

            return condition.w, condition.h
        end
        iconFeature.GLYPH = 16
        iconFeature.size = function()
            return iconFeature.GLYPH
        end
        iconFeature.shadowSlice = function()
            local condition = iconArtUi.shadow or {}

            return condition.pad or 12, condition.slice or 20
        end

        return iconFeature
    end
    end)()

