    modules["ui/inputguard"] = (function()
    -- ======================================================================
    -- ui/inputguard —— 输入拦截（菜单打开时屏蔽游戏输入）
    -- 清理：删除无用语句 0 处，重命名 13 个变量
    -- ======================================================================
    return function(input)
        local inputguardFeature, state, enabled = {}, {}, false
        inputguardFeature.add = function(object)
            if typeof(object) ~= "table" then
                return
            end
            table.insert(state, object)
            local condition = enabled and typeof(object.block) == "function"
            if condition then
                pcall(object.block)
            end
        end
        inputguardFeature.arm = function()
            local enabledCopy = enabled
            if enabledCopy then
                return
            end
            enabled = true
            for index, item in ipairs(state) do
                if typeof(item.block) == "function" then
                    pcall(item.block)
                end
            end
        end
        inputguardFeature.disarm = function()
            local enabledCopy = enabled
            if not enabledCopy then
                return
            end
            enabled = false
            for index, item in ipairs(state) do
                if typeof(item.release) == "function" then
                    pcall(item.release)
                end
            end
        end
        inputguardFeature.isArmed = function()
            local enabledCopy = enabled

            return enabledCopy
        end

        return inputguardFeature
    end
    end)()

