    modules["ui/line"] = (function()
    -- ======================================================================
    -- ui/line —— 线条绘制
    -- 依赖：ui/create, ui/zindex
    -- 清理：删除无用语句 0 处，重命名 20 个变量
    -- ======================================================================
    return function(requireModule)
        local createUi = requireModule("ui/create")
        local zindexUi = requireModule("ui/zindex")

        return {
            new = function(input, input2)
                return createUi.new(
                    "Frame",
                    {
                        Name = "Line",
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        BorderSizePixel = 0,
                        Visible = false,
                        ZIndex = input2 or zindexUi.HUD,
                        Parent = input
                    }
                )
            end,
            place = function(object, object2, object3, input)
                local vec = object3 - object2
                local value = vec.Magnitude
                object.Size = UDim2.fromOffset(math.max(value, 1), math.max(input or 1, 1))
                object.Position = UDim2.fromOffset((object2.X + object3.X) * 0.5, (object2.Y + object3.Y) * 0.5)
                object.Rotation = value > 0 and math.deg(math.atan2(vec.Y, vec.X)) or 0
            end,
            placeMarked = function(object, object2, object3, object4, input)
                local vec = object4 - object3
                local value = vec.Magnitude
                local max, max2 = math.max(value, 1), math.max(input or 1, 1)
                if object2.width ~= max or object2.height ~= max2 then
                    object2.width = max
                    object2.height = max2
                    object.Size = UDim2.fromOffset(max, max2)
                end
                max2, max = (object3.X + object4.X) * 0.5, (object3.Y + object4.Y) * 0.5
                if object2.x ~= max2 or object2.y ~= max then
                    object2.x = max2
                    object2.y = max
                    object.Position = UDim2.fromOffset(max2, max)
                end
                max = value > 0 and math.deg(math.atan2(vec.Y, vec.X)) or 0
                if object2.rotation ~= max then
                    object2.rotation = max
                    object.Rotation = max
                end
            end
        }
    end
    end)()

