    -- ======================================================================
    -- ui/theme —— 主题色板
    -- 清理：删除无用语句 0 处，重命名 24 个变量
    -- ======================================================================
    return function(input)
        local themeFeature, state = {}, {__mode = "k"}
        local result, state2 = setmetatable({}, state), {}
        local color = Color3.fromRGB(255, 125, 247)

        local function applyTheme(entry, key, value)
            if typeof(key) == "function" then
                pcall(key, entry, value)
            else
                pcall(
                    function()
                        entry[key] = value
                    end
                )
            end
        end
        themeFeature.follow = function(key, value)
            if not key or not value then
                return key
            end
            result[key] = value
            applyTheme(key, value, color)

            return key
        end
        themeFeature.unfollow = function(key)
            if key then
                result[key] = nil
            end
        end
        themeFeature.onChange = function(value)
            if typeof(value) ~= "function" then
                return function() end
            end
            table.insert(state2, value)

            return function()
                for index, item in ipairs(state2) do
                    if item == value then
                        table.remove(state2, index)

                        return
                    end
                end
            end
        end
        themeFeature.get = function()
            local colorCopy = color

            return colorCopy
        end
        themeFeature.set = function(value)
            if typeof(value) ~= "Color3" then
                return
            end
            color = value
            for index, item in pairs(result) do
                applyTheme(index, item, color)
            end

            for index, item in ipairs(state2) do
                pcall(item, color)
            end
        end
        themeFeature.count = function()
            local value = 0
            for index in pairs(result) do
                value += 1
            end

            return value
        end

        return themeFeature
    end
    end)()

