            end
            state = {}
            resultCopy = result2
            resultCopy.Text = tostring(value2 or "")
            for index, item in ipairs(input) do
                buildWarning(index, item.label, item.primary, item.value)
            end
            result.Visible = true
            result.BackgroundTransparency = 1
            value2 = parent
            value2.Position = UDim2.new(0.5, 0, 0.5, warningFeature.RISE)
            warningFeature.resize()
            motionUi.to(result, warningFeature.INFO, {BackgroundTransparency = warningFeature.VEIL})
            local value3, parentCopy, value4, state2 = motionUi.to, parent, warningFeature.INFO, {}
            state2.Position = UDim2.fromScale(0.5, 0.5)
            value3(parentCopy, value4, state2)
            value = coroutine.running()

            return coroutine.yield()
        end
        warningFeature.alert = function(input)
            return checkWarning(input, {{label = warningFeature.OK, primary = true, value = true}})
        end
        warningFeature.confirm = function(input)
            return checkWarning(
                input,
                {
                    {label = warningFeature.NO, primary = false, value = false},
                    {label = warningFeature.YES, primary = true, value = true}
                }
            )
        end
        warningFeature.isOpen = function()
            local valueCopy = value

            return valueCopy ~= nil
        end
        warningFeature.reset = function()
            skinUiCopy, result, parent, result2, parent2, instance, state, value = 
                nil,
                nil,
                nil,
                nil,
                nil,
                nil,
                {},
                nil
        end

        return warningFeature
    end
    end)()

    modules["ui/zindex"] = (function()
    -- ======================================================================
    -- ui/zindex —— 层级常量
    -- 清理：删除无用语句 0 处，重命名 1 个变量
    -- ======================================================================
    return function(input)
        return {
            HUD = 1,
            BUBBLE = 8,
            WORLD = 10,
            WINDOW = 20,
            WIDGET = 30,
            POPUP = 50,
            POPUP_CONTENT = 60,
            POPUP_NESTED = 65,
            POPUP_NESTED_CONTENT = 70,
            TOOLTIP = 80,
            MODAL = 90,
            TOP = 100
        }
    end
    end)()

    return modules
end
